SELECT r.field_id AS role, min(r.notice_id) AS first_notice, count(*) AS refs, c.code AS country, tp.value AS tpo_name, org.value AS org_name FROM notice_ids r CROSS JOIN notice_sections s ON s.notice_id = r.notice_id AND s.section_id = r.value CROSS JOIN notice_texts tp ON tp.notice_id = r.notice_id AND tp.section_id = r.value AND tp.field_id = 'BT-500-Organization-TouchPoint' AND tp.ordinal = 0 CROSS JOIN notice_texts org ON org.notice_id = r.notice_id AND org.section_id = s.parent_section_id AND org.field_id = 'BT-500-Organization-Company' AND org.ordinal = 0 LEFT JOIN notice_codes c ON c.notice_id = r.notice_id AND c.section_id = s.parent_section_id AND c.field_id = 'BT-514-Organization-Company' AND c.ordinal = 0 WHERE r.notice_id BETWEEN 47408000 AND 47415999 AND +r.is_ref = 1 AND +r.field_id LIKE 'OPT-301-%' AND +r.value LIKE 'TPO-%' AND lower(trim(tp.value)) <> lower(trim(org.value)) GROUP BY 1, 4, 5, 6 ORDER BY 3 DESC LIMIT 60
